export function totalizar(valores) {
  if (!Array.isArray(valores) || valores.some(v => typeof v !== "number" || !Number.isFinite(v))) {
    throw new TypeError("Informe uma lista de números finitos.");
  }
  return valores.reduce((a, b) => a + b, 0);
}

