import csv
import json
from decimal import Decimal
from pathlib import Path


def resumir(caminho):
    totais = {}
    with Path(caminho).open(encoding="utf-8", newline="") as arquivo:
        for linha in csv.DictReader(arquivo):
            valor = Decimal(linha["valor"])
            if not valor.is_finite():
                raise ValueError("Valor não finito")
            categoria = linha["categoria"]
            totais[categoria] = totais.get(categoria, Decimal(0)) + valor
    return {chave: str(valor) for chave, valor in sorted(totais.items())}


if __name__ == "__main__":
    print(json.dumps(resumir(Path(__file__).with_name("entrada.csv")), ensure_ascii=False, indent=2))

